head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldfil05102";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_loadList();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldfil05102.onpageload' });
    }
};

/**
 * @method
 * @name init_loadList
 * @description 초기 목록 조회 — as-is 는 진입 자체가 조회였다
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_loadList = async function () {
    // 초기 목록 — as-is 는 진입 자체가 조회였다(근거: reuse_tx). 진입점 합성이 이 단계를 잇는다.
    await scwin.tx_fn_documentWrite();
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name grd_formPage_oncellclick
 * @description grd_formPage 셀 클릭 이벤트
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_formPage_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_formPage');
        if (!dl) { /* TODO Stage2: [sdd] 행 동작 대상 목록 없음: dlt_formPage */ return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; }
        if (r["formCd"] === '70931') { await scwin.goWrite(r["formCd"], r["formVer"], r["engFormCd"], r["engFormVer"], r["formAdmInstTpCd"], r["inqdisclsTpCd"], "0", r["formUpclssCd"], r["rsnClssCd"], r["applFormYn"], r["ldMktTpCd"]); return; }
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_formPage.oncellclick' });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_documentWrite
 * @description document Write 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_documentWrite = async function () {
    const sbmOptions = {
        id: "tx_fn_documentWrite",
        method: "post",
        action: "/submission/disclosure.do?method=searchDisclosureDocument",
        ref: "dma_documentWriteReq",
        target: "dlt_formPage=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fn_goWrite
 * @description go Write 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_goWrite = async function () {
    const sbmOptions = {
        id: "tx_fn_goWrite",
        method: "post",
        action: "/submission/disclosurereg.do?method=registerDisclosure",
        ref: "dma_goWriteReq",
        target: "dlt_formPage=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name documentWrite
 * @description document Write 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.documentWrite = async function () {
    (document.writeForm || { elements: [] }).action = '/submission/disclosure.do?method=searchDisclosureDocument';
    await scwin.tx_fn_documentWrite();
};

/**
 * @method
 * @name registerProcess
 * @description register Process 처리
 * @param {*} applNo applNo
 * @param {*} docNo docNo
 * @param {String} formCd formCd
 * @param {*} formVer formVer
 * @param {String} wrtrptMaindocTpCd wrtrptMaindocTpCd
 * @param {*} method method
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.registerProcess = async function (applNo, docNo, formCd, formVer, wrtrptMaindocTpCd, method) {
    $c.util.getComponent('dma_documentWriteReq').set('applNo', applNo);
    if (applNo.length === 14) {
        await scwin.documentWrite();
    } else {
        await scwin.registerMessage('문서불러오기에 실패하였습니다. 잠시후 다시 해주시기 바랍니다.');
    }
};

/**
 * @method
 * @name registerMessage
 * @description register Message 처리
 * @param {String} msg 항목명
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.registerMessage = async function (msg) {
    await $c.win.alert(msg);
};

/**
 * @method
 * @name goWrite
 * @description go Write 처리
 * @param {String} formCd formCd
 * @param {*} formVer formVer
 * @param {String} engFormCd engFormCd
 * @param {*} engFormVer engFormVer
 * @param {String} formAdmInstTpCd formAdmInstTpCd
 * @param {String} inqdisclsTpCd inqdisclsTpCd
 * @param {String} langTpCd langTpCd
 * @param {String} formUpclssCd formUpclssCd
 * @param {String} rsnClssCd rsnClssCd
 * @param {String} applFormYn applFormYn
 * @param {String} ldMktTpCd ldMktTpCd
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.goWrite = async function (formCd, formVer, engFormCd, engFormVer, formAdmInstTpCd, inqdisclsTpCd, langTpCd, formUpclssCd, rsnClssCd, applFormYn, ldMktTpCd) {
    $c.util.getComponent('dma_documentWriteReq').set('disclsMaindocFormCd', formCd);
    $c.util.getComponent('dma_documentWriteReq').set('disclsMaindocFormVer', formVer);
    $c.util.getComponent('dma_documentWriteReq').set('formCd', formCd);
    $c.util.getComponent('dma_documentWriteReq').set('formVer', formVer);
    $c.util.getComponent('dma_documentWriteReq').set('langTpCd', langTpCd);
    $c.util.getComponent('dma_documentWriteReq').set('formUpclssCd', formUpclssCd);
    $c.util.getComponent('dma_documentWriteReq').set('rsnClssCd', rsnClssCd);
    $c.util.getComponent('dma_documentWriteReq').set('ldMktTpCd', ldMktTpCd);
    $c.util.getComponent('dma_documentWriteReq').set('disclsMaindocFormCd', formCd);
    $c.util.getComponent('dma_documentWriteReq').set('disclsMaindocFormVer', formVer);
    $c.util.getComponent('dma_documentWriteReq').set('formCd', formCd);
    $c.util.getComponent('dma_documentWriteReq').set('formVer', formVer);
    $c.util.getComponent('dma_documentWriteReq').set('langTpCd', langTpCd);
    $c.util.getComponent('dma_documentWriteReq').set('formUpclssCd', formUpclssCd);
    $c.util.getComponent('dma_documentWriteReq').set('rsnClssCd', rsnClssCd);
    $c.util.getComponent('dma_documentWriteReq').set('ldMktTpCd', ldMktTpCd);
    let acptApplTpCd = 'D';
    if (applFormYn === 'Y') {
        acptApplTpCd = 'L';
    }
    $c.util.getComponent('dma_documentWriteReq').set('acptApplTpCd', acptApplTpCd);
    $c.util.getComponent('dma_documentWriteReq').set('acptApplTpCd', acptApplTpCd);
    let engFormYn = 'N';
    if (langTpCd === '1') {
        engFormYn = 'Y';
    }
    $c.util.getComponent('dma_documentWriteReq').set('engFormYn', engFormYn);
    $c.util.getComponent('dma_documentWriteReq').set('engFormYn', engFormYn);
    (document.disclosureFrm || { elements: [] }).action = '/submission/disclosurereg.do?method=registerDisclosure';
    (document.disclosureFrm || { elements: [] }).target = 'tempSaveFrame';
    await scwin.tx_fn_goWrite();
};
